<script setup>
import {computed,ref,watch} from 'vue'
import {call} from './service'
import {readResultFile,validateResults} from './resultImport'
import Icon from './Icon.vue'
const props=defineProps({rooms:Array,data:Object})
const emit=defineEmits(['published','notify'])
const form=ref({classroom:props.rooms[0]?.name||'',term:'Semester 1',credits:3}),rows=ref([]),error=ref(''),notice=ref(''),fileName=ref(''),busy=ref(false),confirmed=ref(false),replace=ref(false),page=ref(0)
const checked=computed(()=>validateResults(rows.value,props.data.enrollments,form.value))
const errors=computed(()=>checked.value.filter(r=>r.errors.length).length)
const existing=computed(()=>checked.value.filter(r=>props.data.results.some(old=>old.student===r.student&&old.classroom===r.classroom&&old.term===r.term)).length)
watch(form,()=>confirmed.value=false,{deep:true})
async function upload(event){const file=event.target.files[0];if(!file)return;busy.value=true;rows.value=[];confirmed.value=false;replace.value=false;error.value='';notice.value='';fileName.value=file.name;page.value=0;try{const result=await readResultFile(file);rows.value=result.rows;notice.value=result.note}catch(e){error.value=e.message}finally{busy.value=false;event.target.value=''}}
function template(){const ids=props.data.enrollments.filter(e=>e.classroom===form.value.classroom&&e.active!==0).map(e=>e.student);const content='Student ID,Grade,Credits\r\n'+ids.map(id=>id+',,'+form.value.credits).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='course-results-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function publish(){if(!confirmed.value||errors.value||!rows.value.length)return;busy.value=true;error.value='';try{const result=await call('publish_results_bulk',{data:{rows:checked.value.map(({errors,line,...r})=>r),replace:replace.value}});rows.value=[];confirmed.value=false;notice.value=result.count+' results published together.';emit('published');emit('notify',notice.value)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="panel bulk-results"><div class="section-heading"><div><span class="eyebrow">ONE UPLOAD. THE WHOLE CLASS.</span><h2>Publish course results in bulk</h2><p>Excel, CSV or a text-based PDF. Review first, publish together.</p></div><Icon name="FileSpreadsheet" :size="30"/></div><div class="form-row"><label>Course / classroom<select v-model="form.classroom"><option v-for="r in rooms" :value="r.name">{{r.subject}}</option></select></label><label>Term / semester<input v-model="form.term" maxlength="50" required></label><label>Default credits<input v-model.number="form.credits" type="number" min="0.5" max="60" step="0.5"></label></div><div class="result-dropzone"><span class="stat-icon violet"><Icon name="Upload" :size="26"/></span><div><h3>{{busy?'Reading your results…':fileName||'Bring your class results here'}}</h3><p>Up to 1,000 results · 5 MB · .xlsx, .csv, .pdf</p><input type="file" aria-label="Upload course results" accept=".xlsx,.csv,.pdf" :disabled="busy" @change="upload"></div><button class="button subtle" :disabled="busy" @click="template">Download class template</button></div><p class="field-help">Use columns <b>Student ID, Grade, Credits</b>. The template includes this class’s student IDs; open it in Excel and fill the grades. Only the first Excel worksheet is read. PDFs need selectable text in that same column order; scanned or differently arranged PDFs must be converted to the template. No files are sent to AI.</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="form-note" role="status">{{notice}}</p><template v-if="rows.length"><div class="inline spread"><h3>{{rows.length}} results to review</h3><span class="badge" :class="errors?'amber':'green'">{{errors?errors+' rows need correction':'All student IDs and grades matched'}}</span></div><div class="table-wrap"><table><thead><tr><th>Source row</th><th>Student ID</th><th>Grade</th><th>Credits</th><th>Validation</th></tr></thead><tbody><tr v-for="r in checked.slice(page*20,page*20+20)"><td>{{r.line}}</td><td>{{r.student}}</td><td>{{r.grade}}</td><td>{{r.credits}}</td><td>{{r.errors.join(' · ')||'Ready'}}</td></tr></tbody></table></div><div class="inline spread"><button class="text-button" :disabled="page===0" @click="page--">Previous</button><small>{{page+1}} / {{Math.ceil(rows.length/20)}}</small><button class="text-button" :disabled="(page+1)*20>=rows.length" @click="page++">Next</button></div><p v-if="errors" class="field-help">Correct the highlighted rows in the source file and upload again. Nothing is published while a row is invalid.</p><label v-if="existing" class="checkbox-label"><input v-model="replace" type="checkbox">Replace {{existing}} existing result(s) for this course and term</label><label class="checkbox-label"><input v-model="confirmed" type="checkbox">I compared these rows with the original file and confirm the results.</label><button class="button primary" :disabled="busy||errors>0||!confirmed||!form.term.trim()||(existing>0&&!replace)" @click="publish">Publish {{rows.length}} results</button></template></section></template>
<style scoped>.bulk-results label{display:block;margin:14px 0;font-size:12px}.bulk-results input:not([type=checkbox]),.bulk-results select{display:block;width:100%;border:1px solid #e3dbea;background:#fff;padding:11px;border-radius:10px;margin-top:7px}.result-dropzone{display:flex;align-items:center;gap:18px;border:1.5px dashed #c7b4de;background:#faf7fd;padding:23px;border-radius:18px}.result-dropzone>div{flex:1;min-width:0}.result-dropzone h3{font-size:15px;overflow-wrap:anywhere;margin:0 0 6px}.result-dropzone p{font-size:11px;color:#92829e;margin:0}.result-dropzone input{font-size:11px;border:0!important;padding:5px!important;background:none!important}.bulk-results .checkbox-label{display:flex;align-items:center;gap:8px}.bulk-results .field-help{line-height:1.8}.bulk-results h2{margin-top:8px}@media(max-width:760px){.result-dropzone{flex-wrap:wrap;padding:16px}.bulk-results .form-row{flex-wrap:wrap;display:flex}.bulk-results .form-row label{flex:1 1 140px}}
</style>
